#include "study_support.h"
#include <cuda_runtime.h>
#include <omp.h>
#include "../bmf-cuda/src/bit_vector_functions.h"
#define private public
#include "../bmf-cuda/src/cuBool_gpu.cuh"
#undef private
static void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
template<class T>void guard(T*&p,size_t n){ck(cudaFree(p));uint32_t*b;ck(cudaMalloc(&b,(n+16)*4));std::vector<uint32_t>v(n+16,0xdeadbeef);ck(cudaMemcpy(b,v.data(),v.size()*4,cudaMemcpyHostToDevice));p=(T*)(b+8);}
template<class T>void capture(std::vector<double>&out,T*p,size_t n){std::vector<T>v(n);ck(cudaMemcpy(v.data(),p,n*sizeof(T),cudaMemcpyDeviceToHost));for(T x:v)out.push_back(x);}
static std::pair<double,std::vector<double>> run(){auto cs=cases();std::vector<double>prefix,out;double sec=0;for(auto&c:cs){cuBool<uint32_t>b(c.C,c.h,c.w,c.density,1);auto&hh=b.activeExperiments[0];guard(b.d_C,padded(c).size());guard(hh.d_A,c.h);guard(hh.d_B,c.w);guard(hh.d_distance_,1);auto pad=padded(c);ck(cudaMemcpy(b.d_C,pad.data(),pad.size()*4,cudaMemcpyHostToDevice));capture(prefix,b.d_C,pad.size());cuBool<uint32_t>::cuBool_config cfg;cfg.verbosity=0;cfg.factorDim=c.dim;cfg.linesAtOnce=112;cfg.maxIterations=c.iterations;cfg.seed=c.seed;cfg.tempStart=c.temp;cfg.tempEnd=-1;cfg.reduceStep=c.reduce_step;cfg.reduceFactor=c.reduce_factor;cfg.flipManyChance=c.chance;cfg.flipManyDepth=2;cfg.weight=c.weight;cfg.distanceThreshold=-1;cfg.stuckIterationsBeforeBreak=10000;ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();b.runMultiple(c.runs,cfg);ck(cudaDeviceSynchronize());sec+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();capture(out,hh.d_A,c.h);capture(out,hh.d_B,c.w);capture(out,hh.d_distance_,1);for(uint32_t i=0;i<c.h;i++)out.push_back(b.bestFactors.d_A[i]);for(uint32_t i=0;i<c.w;i++)out.push_back(b.bestFactors.d_B[i]);out.push_back(*b.bestFactors.distance_);for(float x:b.getDistances())out.push_back(x);std::vector<uint32_t>after(pad.size());ck(cudaMemcpy(after.data(),b.d_C,pad.size()*4,cudaMemcpyDeviceToHost));if(after!=pad)throw std::runtime_error("Cmodified");auto guards=[&](auto*p,size_t n){capture(out,(uint32_t*)p-8,8);capture(out,(uint32_t*)p+n,8);};guards(b.d_C,pad.size());guards(hh.d_A,c.h);guards(hh.d_B,c.w);guards(hh.d_distance_,1);b.d_C-=8;hh.d_A-=8;hh.d_B-=8;hh.d_distance_-=8;}prefix.insert(prefix.end(),out.begin(),out.end());return {sec,prefix};}
int main(){try{run();for(int trial=1;trial<=5;trial++){auto result=run();std::string path="trial"+std::to_string(trial)+".bin";std::ofstream f(path,std::ios::binary);f.write((char*)result.second.data(),result.second.size()*8);f.close();check(result.second,cases());std::cout<<std::setprecision(17)<<"\nSTUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<result.first<<",\"correct\":true,\"checked_values\":"<<result.second.size()<<",\"max_abs_error\":0,\"max_rel_error\":null,\"timing_region\":\"complete_two_restart_single_slot_factorization_sum3cases\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\""<<path<<"\",\"dtype\":\"float64\",\"count\":"<<result.second.size()<<",\"byte_order\":\"little\"}}\n";}}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
